下面程序用尾插法建立单链表，再调用 `reverse` 把它整体反转后输出，请填空。

```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node *next;
};

/* 反转整条链表，返回新的表头 */
struct Node *reverse(struct Node *head)
{
    struct Node *prev = NULL, *cur = head, *next;

    while (cur != NULL) {
        next = ①;
        cur->next = ②;
        prev = cur;
        cur = ③;
    }
    return prev;
}

int main(void)
{
    int x;
    struct Node *head = NULL, *tail = NULL, *p;

    while (scanf("%d", &x) == 1 && x != -1) {
        p = (struct Node *)malloc(sizeof(struct Node));
        if (p == NULL)
            return 1;
        p->data = x;
        p->next = NULL;
        if (head == NULL)
            head = tail = p;
        else {
            tail->next = p;
            tail = p;
        }
    }

    head = reverse(head);

    for (p = head; p != NULL; p = p->next)
        printf("%d ", p->data);
    printf("\n");
    return 0;
}
```

