#include <stdio.h>
#include <string.h>

enum Op {
    OP_ADD,
    OP_SUB,
    OP_MUL,
    OP_COUNT
};

static const char *names[OP_COUNT] = {"ADD", "SUB", "MUL"};

enum Op to_op(const char *s)
{
    if (strcmp(s, "ADD") == 0)
        return OP_ADD;
    if (strcmp(s, "SUB") == 0)
        return OP_SUB;
    return OP_MUL;
}

int main(void)
{
    char buf[16];
    int n, i;
    int cnt[OP_COUNT] = {0};

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%15s", buf);
        cnt[to_op(buf)]++;
    }

    for (i = 0; i < OP_COUNT; i++)
        printf("%s %d\n", names[i], cnt[i]);
    return 0;
}
